                    con.execute(\"INSERT INTO transfers VALUES('red','k','a','b',10)\")
                    con.execute(\"INSERT INTO audit VALUES('red','k','a','b',10)\")
            else:
                vault.transfer(path,'red','a','b',10,'k')
            with sqlite3.connect(path) as con:
                outcomes.append(list(con.execute('SELECT * FROM log')))
        print(case, outcomes, 'MATCH' if outcomes[0]==outcomes[1] else 'MISMATCH')
        assert outcomes[0] == outcomes[1]
